unsigned int fn_01(const unsigned char *buf, unsigned int len)
{
    unsigned int i, j, k, l, m, n, o, p, q, r, s, t, u, v, w, x, y, z;
    unsigned int crc;

    crc = 0xffffffff;
    for (i = 0; i < len; i++) {
        crc = (crc >> 8) ^ crc_table[(crc ^ buf[i]) & 0xff];
    }
    return ~crc;
}
